import { Routes } from "@angular/router";
import { UsuarioInternoGuard } from "../guards/user-type.guard";
import { UsuarioExternoGuard } from "../guards/user-type.guard";

export const mainRoutes: Routes = [
  {
    path: '',
    redirectTo: 'inicio',
    pathMatch: 'full'
  },
  {
    path: 'inicio',
    loadComponent: () => import('./inicio/inicio.component').then(c => c.InicioComponent),
    canActivate: [UsuarioInternoGuard]
  },
  {
    path: 'usuarios',
    title: 'Usuarios',
    loadChildren: () => import('./usuarios/usuarios.routes').then(m => m.usuariosRoutes),
    canActivate: [UsuarioInternoGuard]
  },
  {
    path: 'externos',
    title: 'Externos',
    loadChildren: () => import('./externos/externos.routes').then(m => m.externosRoutes),
    canActivate: [UsuarioExternoGuard]
  },
  {
    path: 'empresas',
    loadChildren: () => import('./empresas/empresas.routes').then(m => m.empresasRoutes),
    canActivate: [UsuarioInternoGuard]
  },
  {
    path: 'tramites',
    loadChildren: () => import('./tramites/tramites.routes').then(m => m.tramitesRoutes),
    canActivate: [UsuarioInternoGuard]
  }
]