import { Injectable, inject } from '@angular/core';
import { CanActivate, Router } from '@angular/router';
import { LocalStorageService } from '../services/localStorage/local-storage.service';

@Injectable({
  providedIn: 'root'
})
export class UsuarioExternoGuard implements CanActivate {
  private localStorageService = inject(LocalStorageService);
  private router = inject(Router);

  canActivate(): boolean {
    if (!this.localStorageService.esUsuarioExterno()) {
      this.router.navigate(['/main/inicio']);
      return false;
    }
    return true;
  }
}

@Injectable({
  providedIn: 'root'
})
export class UsuarioInternoGuard implements CanActivate {
  private localStorageService = inject(LocalStorageService);
  private router = inject(Router);

  canActivate(): boolean {
    if (!this.localStorageService.exUsuarioInterno()) {
      this.router.navigate(['/main/externos/inicio']);
      return false;
    }
    return true;
  }
}
